use crate::init::uniform;
use crate::qat::{dequantize_weight_3bit,quantize_weight_3bit,Bits};
use ndarray::{Array1,Array2};
#[derive(Clone,Debug)]pub struct RwkvCmix{pub channels:usize,pub layer_id:usize,pub n_layer:usize,pub x_k:Array1<f32>,pub key:Array2<f32>,pub value:Array2<f32>,pub qat_3bit:bool,pub qat_bits:u8}
impl RwkvCmix{pub fn new(channels:usize,layer_id:usize,n_layer:usize)->Self{Self::new_seeded(channels,layer_id,n_layer,0x434d_4958_4b4559)}pub fn new_seeded(channels:usize,layer_id:usize,n_layer:usize,seed:u64)->Self{assert!(channels>0&&n_layer>0&&layer_id<n_layer);let r=1.0-layer_id as f32/n_layer as f32;let x_k=Array1::from_iter((0..channels).map(|i|{let d=i as f32/channels as f32;1.0-d.powf(r.powi(4))}));let hidden=channels*4;let scale=0.5/(channels as f32).sqrt();Self{channels,layer_id,n_layer,x_k,key:uniform(channels,hidden,-scale,scale,seed^layer_id as u64),value:Array2::zeros((hidden,channels)),qat_3bit:false,qat_bits:0}}pub fn from_weights(x_k:Array1<f32>,key:Array2<f32>,value:Array2<f32>,layer_id:usize,n_layer:usize)->Self{let channels=x_k.len();assert_eq!(key.dim(),(channels,value.nrows()));assert_eq!(value.ncols(),channels);Self{channels,layer_id,n_layer,x_k,key,value,qat_3bit:false,qat_bits:0}}pub fn with_qat_3bit(self,on:bool)->Self{self.with_qat_bits(if on{3}else{0})}pub fn with_qat_bits(mut self,bits:u8)->Self{assert!(matches!(bits,0|2|3|4|8));self.qat_bits=bits;self.qat_3bit=bits==3;self}pub(crate)fn effective_weights(&self)->(Array2<f32>,Array2<f32>){match self.qat_bits{0=>(self.key.clone(),self.value.clone()),3=>{let kt=self.key.t().to_owned();let(kp,ks)=quantize_weight_3bit(&kt);let k=dequantize_weight_3bit(&kp,&ks,kt.dim()).t().to_owned();let(vp,vs)=quantize_weight_3bit(&self.value);(k,dequantize_weight_3bit(&vp,&vs,self.value.dim()))},2|4|8=>{let b=Bits::from_bits(self.qat_bits).unwrap();let k=crate::qat::fake_quantize(&self.key.t().to_owned(),b).t().to_owned();let v=crate::qat::fake_quantize(&self.value.t().to_owned(),b).t().to_owned();(k,v)},_=>unreachable!()}}fn mixed(&self,x:&Array2<f32>,prev:Option<&Array1<f32>>)->Array2<f32>{let mut m=x.clone();for t in 0..x.nrows(){for c in 0..self.channels{let p=if t==0{prev.map_or(0.0,|v|v[c])}else{x[[t-1,c]]};m[[t,c]]=x[[t,c]]+(p-x[[t,c]])*self.x_k[c]}}m}fn relu_squared(v:f32)->f32{let v=v.max(0.0);v*v}fn linear(&self,input:&Array2<f32>,weight:&Array2<f32>)->Array2<f32>{match self.qat_bits{2|4|8=>{let bits=Bits::from_bits(self.qat_bits).unwrap();let(w,s)=crate::qat::quantize_weight(&weight.t().to_owned(),bits);let values=crate::gpu::packed_linear(input.as_slice().unwrap(),&w,&s,input.nrows(),weight.ncols(),weight.nrows(),self.qat_bits).unwrap();Array2::from_shape_vec((input.nrows(),weight.ncols()),values).unwrap()},3=>{let(packed,scales)=quantize_weight_3bit(weight);let quantized=dequantize_weight_3bit(&packed,&scales,weight.dim());input.dot(&quantized.t())},_=>input.dot(&weight.t())}}pub fn forward(&self,x:&Array2<f32>,prev:Option<&Array1<f32>>)->(Array2<f32>,Array1<f32>){let m=self.mixed(x,prev);let mut h=self.linear(&m,&self.key);h.mapv_inplace(Self::relu_squared);(self.linear(&h,&self.value),x.row(x.nrows()-1).to_owned())}pub fn forward_selected(&self,x:&Array2<f32>,prev:Option<&Array1<f32>>)->Array2<f32>{let m=self.mixed(x,prev);let mut h=self.linear(&m,&self.key);h.mapv_inplace(Self::relu_squared);self.linear(&h,&self.value)}pub fn forward_rows(&self,x:&Array2<f32>,prev:Option<&Array1<f32>>,rows:&[usize])->Array2<f32>{let mut m=Array2::zeros((rows.len(),self.channels));for(o,&t)in rows.iter().enumerate(){for c in 0..self.channels{let p=if t==0{prev.map_or(0.0,|v|v[c])}else{x[[t-1,c]]};m[[o,c]]=x[[t,c]]+(p-x[[t,c]])*self.x_k[c]}}let mut h=self.linear(&m,&self.key);h.mapv_inplace(Self::relu_squared);self.linear(&h,&self.value)}pub fn parameter_count(&self)->usize{self.x_k.len()+self.key.len()+self.value.len()}}
#[cfg(test)]mod tests{use super::*;#[test]fn bit_widths_execute(){let x=Array2::ones((2,8));for b in[2u8,3,4,8]{let l=RwkvCmix::new(8,0,4).with_qat_bits(b);let(y,_)=l.forward(&x,None);assert!(y.iter().all(|v|v.is_finite()));}}#[test]fn packed_path_matches_shape(){let x=Array2::ones((3,8));let l=RwkvCmix::new(8,0,4).with_qat_bits(4);let(y,_)=l.forward(&x,None);assert_eq!(y.dim(),(3,8));}}
